(()=>{'use strict';
const isDemo=ShelfWiseStore.isDemo;let data,saveQueue=Promise.resolve(),dismissedInsights=new Set(),customFrom='',customTo='';const routeNames={overview:'',sales:'sales',inventory:'inventory','stock-in':'stock-in',purchases:'purchases',customers:'customers',payments:'payments',expenses:'expenses',analytics:'analytics',reports:'reports',settings:'settings',profile:'profile','seasonal-demand':'seasonal-demand','smart-pricing':'smart-pricing',competitors:'competitors'};const routeViews=Object.fromEntries(Object.entries(routeNames).map(([k,v])=>[v,k]));const routeTail=location.pathname.replace(/^\/app\/?/,'').replace(/\/$/,'');let view=routeViews[routeTail]||'overview',modalRoot=document.getElementById('modal'),cart=[],search='',filter='All',period='Last 30 days',saleRequestId=null;function navigate(next){view=routeNames[next]!==undefined?next:'overview';const tail=routeNames[view],url='/app'+(tail?'/'+tail:'')+(isDemo?'?demo=1':'');history.pushState({},'',url);render()}window.addEventListener('popstate',()=>{const tail=location.pathname.replace(/^\/app\/?/,'').replace(/\/$/,'');view=routeViews[tail]||'overview';render()});function save(){saveQueue=saveQueue.catch(()=>{}).then(async()=>{try{data=await ShelfWiseStore.save(data);return true}catch(err){toast(err.message||'Could not save changes');return false}});return saveQueue}async function protectedRequest(fn){await saveQueue;try{const result=await fn();data=result.workspace;return result}catch(err){toast(err.message||'Could not save this transaction');throw err}}
let toastEl=document.getElementById('toast'),toastTimer;function toast(s){toastEl.textContent=s;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2600)}const money=n=>'₹'+Math.round(+n||0).toLocaleString('en-IN');const today=()=>new Date().toISOString().slice(0,10);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let navItems=[['overview','⌂','Overview'],['sales','↗','Sales & Billing'],['inventory','▦','Inventory'],['stock-in','↓','Stock In'],['purchases','▤','Purchases'],['customers','♙','Customers'],['payments','₹','Payments & Credit'],['expenses','◉','Expenses'],['analytics','◷','Analytics & Insights'],['reports','▧','Reports'],['settings','⚙','Settings'],['profile','◉','Profile']];
function shell(){let active=navItems.find(x=>x[0]===view),activeLabel=active?.[2]||({'seasonal-demand':'Seasonal demand','smart-pricing':'Smart pricing',competitors:'Neighbourhood prices'}[view])||'Overview';document.getElementById('root').innerHTML=`<div class="layout"><aside class="side"><div class="brand"><span class="mark">S</span>ShelfWise</div><div class="shop"><div class="shopIcon">🥬</div><div><b>${esc(data.shop.name)}</b><small>${esc(data.shop.category)} shop ⌄</small></div></div><div class="label">WORKSPACE</div><nav class="nav">${navItems.map(x=>`<button class="${view===x[0]?'active':''}" data-view="${x[0]}"><i>${x[1]}</i><span>${x[2]}</span></button>`).join('')}</nav><div class="bottom"><div class="owner"><div class="avatar">👨🏽</div><div><b>${esc(data.shop.owner)}</b><small>${isDemo?'Demo workspace':'Signed in · secure session'}</small></div></div></div></aside><main class="main"><div class="top"><div class="crumb">${esc(data.shop.name)}　/　${activeLabel}</div><div class="tools"><span class="badge">● ${isDemo?'Demo mode':'Shop workspace'}</span>${isDemo?'<a class="outline" href="/register" style="text-decoration:none">Set up my shop</a><button class="outline" id="reset">Reset demo</button>':''}<a class="outline" href="/" style="text-decoration:none">Website</a><div class="accountWrap"><button class="accountButton" id="accountButton" aria-label="Account menu"><img id="headerAvatar" class="headerAvatar" alt=""><span>Account⌄</span></button><div id="accountMenu" class="accountMenu hidden"><button data-view="profile">My Profile</button><button data-view="settings">Settings</button><button id="menuLogout">Logout</button></div></div><button class="icon" id="theme">${document.body.classList.contains('dark')?'☀':'☾'}</button><button class="icon" id="logout" title="Sign out">↪</button></div></div><div id="page"></div></main></div><nav class="mobileNav">${navItems.map(x=>`<button class="${view===x[0]?'active':''}" data-view="${x[0]}"><span>${x[1]}</span>${x[2].split(' ')[0]}</button>`).join('')}</nav>`;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));if(isDemo)document.getElementById('reset').onclick=()=>{if(confirm('Reset the demo shop to its original sample data?'))ShelfWiseStore.resetDemo().then(r=>{data=r.workspace;render();toast('Demo shop reset')}).catch(e=>toast(e.message))};document.getElementById('theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('shelfwise-theme',document.body.classList.contains('dark')?'dark':'light');render()};document.getElementById('logout').onclick=()=>{if(!confirm('Log out of ShelfWise?'))return;if(isDemo){location.href='/';return}ShelfWiseAuth.logout().then(()=>location.replace('/login')).catch(e=>toast(e.message))};refreshHeaderProfile();renderPage()}
function refreshHeaderProfile(){const img=document.getElementById('headerAvatar');if(!img)return;img.src=avatarData(data.shop.owner);if(!isDemo)fetch('/api/profile',{credentials:'same-origin'}).then(r=>r.ok?r.json():null).then(x=>{if(x?.profile?.photo&&img.isConnected)img.src=x.profile.photo}).catch(()=>{});const button=document.getElementById('accountButton'),menu=document.getElementById('accountMenu');button.onclick=()=>menu.classList.toggle('hidden');document.addEventListener('click',e=>{if(!e.target.closest('.accountWrap'))menu.classList.add('hidden')},{once:true});document.getElementById('menuLogout').onclick=()=>document.getElementById('logout').click()}
function head(title,desc,action=''){return `<div class="pagehead"><div><div class="overline">${view==='overview'?'Wednesday · '+new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long'}):'SHOP WORKSPACE'}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}function metric(label,val,hint){return `<div class="card"><div class="metricLabel">${label}<span>↗</span></div><div class="metric">${val}</div><div class="hint">${hint}</div></div>`}function salesToday(){return data.sales.filter(s=>s.date===today()).reduce((a,s)=>a+s.total,0)}function monthSales(){let m=today().slice(0,7);return data.sales.filter(s=>s.date.startsWith(m)).reduce((a,s)=>a+s.total,0)}function pending(){return data.customers.reduce((a,c)=>a+c.balance,0)}function alerts(){let low=data.products.filter(p=>!p.archived&&p.stock<=p.threshold).length;return low}function chart(){let values=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);return data.sales.filter(s=>s.date===d.toISOString().slice(0,10)).reduce((a,s)=>a+s.total,0)});let max=Math.max(...values,1),pts=values.map((v,i)=>`${i*100},${150-(v/max*128)}`).join(' ');return `<div class="chart"><svg viewBox="0 0 600 160" preserveAspectRatio="none"><line x1="0" y1="10" x2="600" y2="10"/><line x1="0" y1="55" x2="600" y2="55"/><line x1="0" y1="100" x2="600" y2="100"/><line x1="0" y1="150" x2="600" y2="150"/><polygon class="fill" points="0,160 ${pts} 600,160"/><polyline class="line" points="${pts}"/></svg></div><div class="sub" style="display:flex;justify-content:space-between"><span>7 days ago</span><span>Today</span></div>`}
function overview(){let monthKey=today().slice(0,7),costs=data.sales.filter(s=>s.date.startsWith(monthKey)).reduce((a,s)=>a+s.cost,0),rev=monthSales(),gross=rev-costs,expenses=data.expenses.reduce((a,e)=>a+e.amount,0),inventory=data.products.reduce((a,p)=>a+p.stock*p.cost,0);let low=data.products.filter(p=>p.stock<=p.threshold);return `${head('Good morning, '+esc(data.shop.owner.split(' ')[0])+' ☀️','Here’s how your shop is doing today.',`<button class="btn" data-action="sale">＋ New sale</button>`)}<div class="cards">${metric('Today’s sales',money(salesToday()),'Sales recorded today')}${metric('Monthly sales',money(rev),'Revenue this month')}${metric('Gross profit',money(gross),'Revenue less product cost')}${metric('Stock value',money(inventory),`${data.products.length} products tracked`)}</div><div class="cards">${metric('Estimated net profit',money(gross-expenses),'Gross profit less recorded expenses')}${metric('Expenses this month',money(expenses),'Operating costs recorded')}${metric('Customer credit',money(pending()),'Outstanding balances')}${metric('Need attention',String(low.length+data.customers.filter(c=>c.due<today()&&c.balance>0).length),'Low stock or overdue')}</div><div class="row"><div class="card"><h2 class="ctitle">Sales trend</h2><div class="sub">Daily revenue · based on recorded transactions</div>${chart()}</div><div class="card"><h2 class="ctitle">Today’s action list</h2><div class="sub">Small steps to keep things running.</div><div class="actions">${data.tasks.slice(0,5).map((t,i)=>`<div class="action"><button class="taskcheck ${t.done?'done':''}" data-task="${i}">${t.done?'✓':''}</button><div style="cursor:pointer" data-goto="${t.view}"><b>${esc(t.text)}</b><small>${esc(t.detail)}</small></div></div>`).join('')}</div><button class="btn secondary" data-view="inventory" style="margin-top:10px">See inventory alerts →</button></div></div><div class="row equal"><div class="card"><h2 class="ctitle">Stock to watch</h2><div class="tablewrap"><table class="table"><thead><tr><th>PRODUCT</th><th>STOCK</th><th>SELLS / DAY</th><th>EST. RUNOUT</th></tr></thead><tbody>${low.slice(0,5).map(p=>`<tr><td>${esc(p.name)}</td><td>${p.stock} ${p.unit}</td><td>${(p.sold/30).toFixed(1)}</td><td>${p.stock?Math.ceil(p.stock/(p.sold/30||1))+' days':'Out of stock'}</td></tr>`).join('')||'<tr><td colspan="4">All products are above reorder levels.</td></tr>'}</tbody></table></div></div><div class="card"><h2 class="ctitle">Business suggestions</h2><div class="actions">${data.products.filter(p=>p.stock<=p.threshold).slice(0,3).map(p=>`<div class="action"><span>✦</span><div><b>Consider ordering ${Math.max(p.threshold*3-p.stock,1)} ${p.unit} of ${esc(p.name)}</b><small>Based on current stock, reorder level, and 30-day sales average.</small></div></div>`).join('')}</div><button class="btn secondary" data-view="analytics">Explore insights →</button></div></div>`}
function inventoryView(){let rows=data.products.filter(p=>!p.archived&&(!search||`${p.name} ${p.sku} ${p.barcode||''} ${p.category}`.toLowerCase().includes(search.toLowerCase()))&&(filter==='All'||(filter==='Low stock'&&p.stock<=p.threshold)||(filter==='Expiry soon'&&p.expiry&&p.expiry<=new Date(Date.now()+7*864e5).toISOString().slice(0,10))));return `${head('Inventory','Products, stock levels, identifiers, and expiry dates.',`<button class="btn secondary" data-action="scanadd">▣ Scan barcode</button><button class="btn" data-action="addproduct">＋ Add product</button>`)}<div class="filters"><input id="search" placeholder="Search product, SKU, or barcode…" value="${esc(search)}"><select id="invfilter">${['All','Low stock','Expiry soon'].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn secondary" data-action="stock">＋ Receive stock</button></div><div class="card"><div class="tablewrap"><table class="table"><thead><tr><th>PRODUCT / SKU</th><th>BARCODE</th><th>CATEGORY</th><th>COST</th><th>PRICE</th><th>STOCK</th><th>VALUE</th><th>UNITS SOLD</th><th>EXPIRY</th><th>STATUS</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><b>${esc(p.name)}</b><br><span class="sub">${esc(p.sku)}</span></td><td>${esc(p.barcode||'—')}</td><td>${esc(p.category)}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td>${p.stock} ${esc(p.unit)}</td><td>${money(p.stock*p.cost)}</td><td>${p.sold}</td><td>${p.expiry||'—'}</td><td><span class="status ${p.stock===0?'bad':p.stock<=p.threshold?'warn':''}">${p.stock===0?'Out of stock':p.stock<=p.threshold?'Low stock':p.expiry&&p.expiry<=new Date(Date.now()+7*864e5).toISOString().slice(0,10)?'Expiring soon':'In stock'}</span></td><td><button class="outline" data-product="${p.id}">Edit</button> <button class="outline" data-qr="${p.id}">QR</button></td></tr>`).join('')||'<tr><td colspan="11" class="empty">No matching products.</td></tr>'}</tbody></table></div><div class="footnote">SKU is your shop’s internal code. Barcode is the manufacturer identifier. Both are searchable and scannable.</div></div>`}
function salesView(){let total=data.sales.reduce((a,s)=>a+s.total,0);return `${head('Sales & Billing','Scan products, confirm payment, and keep a clear sales history.',`<button class="btn" data-action="sale">＋ Create bill</button>`)}<div class="cards">${metric('Today',money(salesToday()),'Confirmed revenue')}${metric('This month',money(monthSales()),'Revenue')}${metric('Sales recorded',data.sales.length,'Sample and new transactions')}${metric('Sales total',money(total),'All recorded revenue')}</div><div class="filters"><input id="salessearch" placeholder="Search invoice or customer…"><button class="btn secondary" data-action="sale">＋ New sale</button></div><div class="card"><h2 class="ctitle">Recent transactions</h2><div class="tablewrap"><table class="table"><thead><tr><th>INVOICE</th><th>DATE</th><th>ITEMS</th><th>PAYMENT</th><th>CUSTOMER</th><th>TOTAL</th><th></th></tr></thead><tbody>${[...data.sales].reverse().map(s=>`<tr><td>${esc(s.id)}</td><td>${s.date}</td><td>${s.items}</td><td>${esc(s.method)}</td><td>${esc(s.customer||'Walk-in')}</td><td>${money(s.total)}</td><td><button class="outline" data-invoice="${s.id}">Print</button> <button class="outline" data-return="${s.id}">Return item</button></td></tr>`).join('')}</tbody></table></div></div>`}
function purchasesView(){return `${head('Purchases','Supplier records, open order drafts, and received stock.',`<button class="btn" data-action="purchase">＋ Record purchase</button>`)}<div class="cards">${metric('Purchase records',data.purchases.length,'Drafts and confirmed receipts')}${metric('Draft orders',data.purchases.filter(p=>p.status==='draft'||p.status==='ordered').length,'Not yet received')}${metric('Received lines',data.purchases.filter(p=>p.status==='received').length,'Stock added after confirmation')}${metric('Draft value',money(data.purchases.filter(p=>p.status==='draft'||p.status==='ordered').reduce((a,p)=>a+p.qty*p.cost,0)),'Planning only · not an expense yet')}</div><div class="card"><h2 class="ctitle">Supplier purchases and drafts</h2><div class="sub">Draft orders count as incoming supply for reorder suggestions but never change inventory.</div><div class="tablewrap"><table class="table"><thead><tr><th>DATE</th><th>STATUS</th><th>SUPPLIER</th><th>PRODUCT</th><th>QTY</th><th>UNIT COST</th><th>BATCH / EXPIRY</th><th>TOTAL</th></tr></thead><tbody>${[...data.purchases].reverse().map(p=>`<tr><td>${esc(p.date)}</td><td><span class="status ${p.status==='draft'?'warn':''}">${p.status==='draft'?'Draft · not received':'Received'}</span></td><td>${esc(p.supplier)}</td><td>${esc(p.product)}</td><td>${p.qty}</td><td>${money(p.cost)}</td><td>${esc(p.batch||'—')} ${p.expiry?'· '+esc(p.expiry):''}</td><td>${money(p.qty*p.cost)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No purchases yet.</td></tr>'}</tbody></table></div></div>`}
function stockInView(){return `${head('Stock In','Receive supplier stock into the same inventory used by billing.',`<button class="btn" data-action="stockin">＋ Scan and receive stock</button>`)}<div class="card"><h2 class="ctitle">Recent stock receipts</h2><div class="sub">Confirmed receipts update on-hand quantities and purchase history together.</div><div class="tablewrap"><table class="table"><thead><tr><th>DATE</th><th>SUPPLIER</th><th>PRODUCT</th><th>QUANTITY</th><th>INVOICE</th></tr></thead><tbody>${[...data.purchases].reverse().slice(0,12).map(p=>`<tr><td>${p.date}</td><td>${esc(p.supplier)}</td><td>${esc(p.product)}</td><td>${p.qty}</td><td>${esc(p.invoice||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No stock receipts recorded.</td></tr>'}</tbody></table></div></div>`}function customersView(){return `${head('Customers','Customer details, credit balances, and payment history.',`<button class="btn" data-action="customer">＋ Add customer</button>`)}<div class="cards">${metric('Customers',data.customers.length,'Saved customer records')}${metric('With a balance',data.customers.filter(c=>c.balance>0).length,'Open credit accounts')}${metric('Outstanding credit',money(pending()),'Across customer accounts')}${metric('Payments recorded',data.customers.reduce((a,c)=>a+c.history.length,0),'Repayments logged')}</div><div class="card"><h2 class="ctitle">Customer list</h2><div class="tablewrap"><table class="table"><thead><tr><th>CUSTOMER</th><th>PHONE</th><th>BALANCE</th><th>DUE DATE</th><th>PAYMENT HISTORY</th><th></th></tr></thead><tbody>${data.customers.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.phone||'—')}</td><td>${money(c.balance)}</td><td>${c.due||'—'}</td><td>${c.history.length} payment${c.history.length===1?'':'s'}</td><td><button class="outline" data-repay="${c.id}">Record payment</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No customers yet. Add a customer to track credit.</td></tr>'}</tbody></table></div></div>`}function paymentsView(){return `${head('Payments & credit','Track customer balances and record partial or full repayments.',`<button class="btn" data-action="customer">＋ Add customer</button>`)}<div class="cards">${metric('Outstanding credit',money(pending()),'All unpaid customer balances')}${metric('Overdue',money(data.customers.filter(c=>c.balance>0&&c.due<today()).reduce((a,c)=>a+c.balance,0)),`${data.customers.filter(c=>c.balance>0&&c.due<today()).length} accounts past due`)}${metric('Customers',data.customers.length,'Credit accounts')}${metric('Repayments recorded',data.customers.reduce((a,c)=>a+c.history.length,0),'Payment entries')}</div><div class="card"><h2 class="ctitle">Customer accounts</h2><div class="tablewrap"><table class="table"><thead><tr><th>CUSTOMER</th><th>PHONE</th><th>BALANCE</th><th>DUE DATE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${data.customers.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.phone)}</td><td>${money(c.balance)}</td><td>${c.due||'—'}</td><td><span class="status ${c.balance>0&&c.due<today()?'bad':''}">${c.balance===0?'Settled':c.due<today()?'Overdue':'Pending'}</span></td><td><button class="outline" data-repay="${c.id}">Record payment</button></td></tr>`).join('')}</tbody></table></div></div>`}
function expensesView(){let total=data.expenses.reduce((a,e)=>a+e.amount,0);return `${head('Expenses','Keep operating costs separate from product purchases and revenue.',`<button class="btn" data-action="expense">＋ Record expense</button>`)}<div class="cards">${metric('Recorded expenses',money(total),'All saved operating costs')}${metric('Expense entries',data.expenses.length,'Individual records')}${metric('This month',money(data.expenses.filter(e=>e.date?.startsWith(today().slice(0,7))).reduce((a,e)=>a+e.amount,0)),'Dated entries this month')}${metric('Net estimate',money(data.sales.reduce((a,x)=>a+x.total-x.cost,0)-total),'Gross profit less recorded expenses')}</div><div class="card"><h2 class="ctitle">Expense history</h2><div class="tablewrap"><table class="table"><thead><tr><th>DATE</th><th>CATEGORY</th><th>NOTE</th><th>AMOUNT</th></tr></thead><tbody>${[...data.expenses].reverse().map(e=>`<tr><td>${esc(e.date||'—')}</td><td>${esc(e.category)}</td><td>${esc(e.note||'—')}</td><td>${money(e.amount)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No expenses recorded yet.</td></tr>'}</tbody></table></div></div>`}function inventoryHealthView(){const list=(data.insights||[]).filter(x=>data.products.some(p=>p.id===x.productId&&!p.archived));const groups={more:[],hold:[],ok:[],review:[]};for(const x of list){if(!x.enoughHistory)groups.review.push(x);else if(x.suggestedQty>0)groups.more.push(x);else if(x.slowMoving||x.excessStock)groups.hold.push(x);else groups.ok.push(x)}groups.more.sort((a,b)=>((b.lowStock?10000:0)+(b.daysToStockout!==null?Math.max(0,1000-b.daysToStockout):0))-((a.lowStock?10000:0)+(a.daysToStockout!==null?Math.max(0,1000-a.daysToStockout):0)));const n=list.length||1,values=[groups.more.length,groups.hold.length,groups.ok.length,groups.review.length],colors=['#ba5848','#d2a044','#28744d','#96a39a'];let acc=0,stops=values.map((v,i)=>{const a=acc;acc+=v/n*100;return `${colors[i]} ${a}% ${acc}%`}).join(',');const card=(x,kind)=>`<article class="card insightCard ${kind==='BUY NOW'?'urgent':kind==='REVIEW'?'review':''}"><div class="metricLabel">${esc(x.name)} <span class="status">${kind}</span></div><div class="sub">${x.stock} ${esc(x.unit)} on hand · ${x.enoughHistory?(x.averageDaily.toFixed(1)+' / day'):'not enough sales history'}</div><b>${kind==='BUY NOW'?'Order '+x.suggestedQty+' '+esc(x.unit):kind==='REVIEW'?'Review manually':kind==='STOCK OK'?'Stock healthy':'Hold order'}</b><div class="sub">${x.daysToStockout!==null?'May run out in '+x.daysToStockout+' days':('Minimum stock '+x.threshold+' '+esc(x.unit))}</div></article>`;return `<section class="card"><h2 class="ctitle">Stock at a glance</h2><div class="insightSummary"><div class="stockDonut" role="img" aria-label="Stock recommendations: Buy more ${values[0]}, hold order ${values[1]}, stock OK ${values[2]}, needs review ${values[3]}" style="border-radius:50%;background:conic-gradient(${stops});display:grid;place-items:center"><div style="width:62%;height:62%;border-radius:50%;background:var(--surface);display:grid;place-content:center;text-align:center"><b>${list.length}</b><small>products</small></div></div><div class="insightLegend">${['BUY MORE','HOLD ORDER','STOCK OK','NEEDS REVIEW'].map((l,i)=>`<span><b>${values[i]}</b>${l}</span>`).join('')}</div></div><div class="insightGroups">${groups.more.slice(0,4).map(x=>card(x,'BUY NOW')).join('')}${groups.hold.slice(0,4).map(x=>card(x,'HOLD ORDER')).join('')}${groups.ok.slice(0,4).map(x=>card(x,'STOCK OK')).join('')}${groups.review.slice(0,4).map(x=>card(x,'REVIEW')).join('')}</div><details class="footnote"><summary>Why this suggestion?</summary><p>Buy More uses the existing server forecast: 65% recent seven-day sales and 35% thirty-day sales, supplier lead time, safety stock, on-hand stock and open orders. Products with insufficient sales history are counted under Needs Review. Each active product appears in exactly one group.</p></details></section>`}
function analyticsView(){const now=new Date(),end=(period==='Custom'&&customTo)||today();let startDate=new Date(now);if(period==='Last 7 days')startDate.setDate(now.getDate()-6);else if(period==='Last 3 months')startDate.setDate(now.getDate()-89);else if(period==='Custom'&&customFrom)startDate=new Date(customFrom+'T00:00:00');else startDate.setDate(now.getDate()-29);const start=(period==='Custom'&&customFrom)||startDate.toISOString().slice(0,10),periodSales=data.sales.filter(s=>s.date>=start&&s.date<=end),periodProfit=periodSales.reduce((a,s)=>a+s.total-s.cost,0)-data.expenses.filter(e=>e.date>=start&&e.date<=end).reduce((a,e)=>a+e.amount,0),todayRevenue=data.sales.filter(s=>s.date===today()).reduce((a,s)=>a+s.total,0),weekStart=new Date(now.getFullYear(),now.getMonth(),now.getDate()-6).toISOString().slice(0,10),weekRevenue=data.sales.filter(s=>s.date>=weekStart&&s.date<=today()).reduce((a,s)=>a+s.total,0),monthRevenue=data.sales.filter(s=>s.date.startsWith(today().slice(0,7))).reduce((a,s)=>a+s.total,0),units=new Map();periodSales.forEach(s=>(s.details||[]).forEach(line=>units.set(line.productId,(units.get(line.productId)||0)+Math.max(0,line.qty-(line.returned||0)))));const best=data.products.map(p=>({...p,periodUnits:units.get(p.id)||0})).sort((a,b)=>b.periodUnits-a.periodUnits).slice(0,5),insights=[...(data.insights||[])].sort((a,b)=>(a.daysToStockout??9999)-(b.daysToStockout??9999));return `${head('Business analytics','The important numbers, without the noise.')} ${intelligenceTabs()}<div class="filters"><div class="pilltabs">${['Last 7 days','Last 30 days','Last 3 months','Custom'].map(x=>`<button class="${period===x?'active':''}" data-period="${x}">${x}</button>`).join('')}</div>${period==='Custom'?`<input id="customFrom" aria-label="Start date" type="date" value="${esc(customFrom)}"><input id="customTo" aria-label="End date" type="date" value="${esc(customTo)}"><button class="btn secondary" data-action="applyrange">Apply dates</button>`:''}</div><div class="cards">${metric('Sales today',money(todayRevenue),'Confirmed sales')}${metric('Sales this week',money(weekRevenue),'Last 7 days')}${metric('Sales this month',money(monthRevenue),'Month to date')}${metric('Estimated profit',money(periodProfit),period+' · sales less cost and expenses')}</div><div class="row equal"><section class="card"><h2 class="ctitle">Sales trend</h2><p class="sub">Daily revenue · confirmed transactions</p>${chart()}</section><section class="card"><h2 class="ctitle">Best-selling products</h2><div class="actions">${best.map((p,i)=>`<div class="action"><span class="status">${i+1}</span><div><b>${esc(p.name)}</b><small>${p.periodUnits} units sold · ${money((p.price-p.cost)*p.periodUnits)} gross profit</small></div></div>`).join('')||'<div class="empty">Confirmed sales will appear here.</div>'}</div></section></div>${inventoryHealthView()}<section class="card" style="margin-top:14px"><h2 class="ctitle">Needs attention</h2><div class="actions">${insights.filter(x=>x.lowStock||x.daysToStockout!==null&&x.daysToStockout<=7).slice(0,5).map(x=>`<div class="action"><span class="status ${x.lowStock?'bad':'warn'}">${x.lowStock?'LOW STOCK':'SOON'}</span><div><b>${esc(x.name)}</b><small>${!x.enoughHistory?'Not enough history · review stock manually':x.suggestedQty>0?`Order ${x.suggestedQty} ${esc(x.unit)} · estimated cover ${x.daysToStockout} days`:`No immediate reorder calculated · estimated cover ${x.daysToStockout} days`}</small></div></div>`).join('')||'<div class="sub">No urgent stock alerts today.</div>'}</div></section>`}
function reportsView(){return `${head('Reports','Choose a report and download a spreadsheet-ready CSV.',`<button class="btn secondary" data-action="expense">＋ Add expense</button>`) }<div class="cards">${['Sales','Inventory','Purchases','Profit & loss'].map((x,i)=>`<div class="card"><div class="metricLabel">${x} report</div><div class="metric" style="font-size:17px">${['Transactions','On-hand stock','Supplier invoices','Revenue & costs'][i]}</div><button class="btn secondary" data-csv="${x}">Download CSV ↓</button></div>`).join('')}</div><div class="card"><h2 class="ctitle">Period summary</h2><div class="filters" style="margin-top:14px"><select id="reportperiod"><option>Daily</option><option>Weekly</option><option selected>Monthly</option><option>Seasonal</option><option>Yearly</option></select><span class="sub">CSV exports include current demo records.</span></div><div class="tablewrap"><table class="table"><tbody><tr><td>Revenue</td><td>${money(monthSales())}</td></tr><tr><td>Cost of goods sold (recorded)</td><td>${money(data.sales.reduce((a,s)=>a+s.cost,0))}</td></tr><tr><td>Operating expenses recorded</td><td>${money(data.expenses.reduce((a,e)=>a+e.amount,0))}</td></tr><tr><td>Customer credit outstanding</td><td>${money(pending())}</td></tr></tbody></table></div></div>`}
function settingsView(){return `${head('Settings','Shop details, appearance, and this browser workspace.') }<div class="row equal"><div class="card"><h2 class="ctitle">Shop profile</h2><div class="formgrid" style="margin-top:16px"><label>Shop name<input id="sname" value="${esc(data.shop.name)}"></label><label>Owner name<input id="ownername" value="${esc(data.shop.owner)}"></label><label>Category<select id="scat">${['Grocery','Convenience store','Produce','Pharmacy','Other'].map(x=>`<option ${data.shop.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Currency<select id="currency"><option>INR · ₹</option></select></label><label class="full">Shop address<input id="saddress" value="${esc(data.shop.address)}"></label><div class="full"><button class="btn" data-action="savesettings">Save shop profile</button></div></div></div><div class="card"><h2 class="ctitle">Appearance & account</h2><div class="action"><div><b>Theme</b><small>Your preference is saved in this browser.</small></div><select id="themeSelect" class="field"><option ${!document.body.classList.contains('dark')?'selected':''}>Light</option><option ${document.body.classList.contains('dark')?'selected':''}>Dark</option></select></div><div class="action"><div><b>${isDemo?'Demo workspace':'Local account workspace'}</b><small>Shop records are stored in the shared ShelfWise database.</small></div></div>${isDemo?'<button class="btn secondary" id="resetsettings">Reset demo data</button>':''}<p class="footnote">This prototype uses server sessions and SQLite storage. Deploy behind HTTPS before using real customer records.</p><a href="/" class="outline" style="display:inline-block;text-decoration:none;margin-top:10px">Back to public website</a></div></div>`}
function intelligenceTabs(){return `<div class="pilltabs intelligenceTabs"><button data-view="analytics">Overview</button><button data-view="seasonal-demand">Seasonal demand</button><button data-view="smart-pricing">Smart pricing</button><button data-view="competitors">Neighbourhood prices</button></div>`}
function intelligenceData(){return data.intelligence||{products:[],monthlyLabels:[],competitorPrices:[],events:[],priceHistory:[],historyDays:0,seasonalityAvailable:false}}
function seasonalDemandView(){const intel=intelligenceData(),items=intel.products||[],seasonal=items.filter(x=>x.seasonalDemand!=='insufficient'),monthly=(intel.monthlyLabels||[]).map((m,i)=>({m,n:items.reduce((a,p)=>a+(p.monthlyUnits?.[i]||0),0)})),max=Math.max(1,...monthly.map(x=>x.n));return `${head('Seasonal demand','Spot repeat changes in demand through the year.')} ${intelligenceTabs()}<div class="cards">${metric('Products analysed',items.length,'Active catalogue')}${metric('Seasonal patterns',seasonal.filter(x=>x.seasonalDemand==='rising').length,'Based on longer-term sales')}${metric('Demand stable',seasonal.filter(x=>x.seasonalDemand==='stable').length,'No clear seasonal peak')}${metric('History available',intel.historyDays+' days','Needs two years for recurring patterns')}</div><div class="row equal"><section class="card"><h2 class="ctitle">Monthly sales · all products</h2><p class="sub">Confirmed units grouped by calendar month; totals reflect available history.</p><div class="seasonBars" role="img" aria-label="Monthly product sales chart">${monthly.map(x=>`<div><span title="${x.n} units" style="height:${Math.max(3,x.n/max*100)}%"></span><small>${x.m}</small></div>`).join('')}</div></section><section class="card"><h2 class="ctitle">Seasonal calendar</h2><p class="sub">Add local events to plan ahead. Events do not change prices or stock automatically.</p><div class="formgrid eventForm"><label>Event name<input id="eventName" placeholder="Local festival or season"></label><label>Start date<input id="eventStart" type="date"></label><label>End date<input id="eventEnd" type="date"></label><label>Note<input id="eventNote" placeholder="Optional shop note"></label></div><button class="btn secondary" id="saveEvent" style="margin-top:10px">Add event</button><div class="actions">${(intel.events||[]).map(e=>`<div class="action"><div><b>${esc(e.name)}</b><small>${esc(e.start_date)} – ${esc(e.end_date)}${e.note?' · '+esc(e.note):''}</small></div></div>`).join('')||'<div class="empty">No local events added yet.</div>'}</div></section></div><section class="card"><h2 class="ctitle">Product demand patterns</h2><div class="tablewrap"><table class="table"><thead><tr><th>PRODUCT</th><th>MONTHLY DEMAND</th><th>STATUS</th><th>SUGGESTED ACTION</th></tr></thead><tbody>${items.map(p=>`<tr><td><b>${esc(p.name)}</b><br><span class="sub">${esc(p.sku)}</span></td><td>${(p.monthlyUnits||[]).reduce((a,b)=>a+b,0)} recorded units</td><td><span class="status ${p.seasonalDemand==='rising'?'warn':''}">${p.seasonalDemand==='insufficient'?'Insufficient data':p.seasonalDemand==='rising'?'Rising in this season':p.seasonalDemand==='falling'?'Falling in this season':'Stable'}</span></td><td>${p.seasonalDemand==='insufficient'?'Review manually':p.seasonalDemand==='rising'?'Prepare stock ahead of peak':p.seasonalDemand==='falling'?'Reduce future ordering':'Maintain normal ordering'}${p.seasonalChangePercent!==null&&p.seasonalChangePercent!==undefined?`<br><span class="sub">${p.seasonalChangePercent>0?'+':''}${p.seasonalChangePercent}% vs annual monthly baseline</span>`:''}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Add products and confirm sales to see patterns.</td></tr>'}</tbody></table></div>${!intel.seasonalityAvailable?'<p class="footnote">Not enough historical data for a reliable seasonal prediction. A recurring pattern requires at least two years of shop sales.</p>':''}</section>`}
function smartPricingView(){const intel=intelligenceData(),items=intel.products||[];return `${head('Smart pricing','Use your costs, sales and verified local prices to review decisions.')} ${intelligenceTabs()}<div class="cards">${metric('Products',items.length,'Current catalogue')}${metric('Verified comparisons',items.filter(x=>x.competitorCount).length,'Price checks from last 30 days')}${metric('Suggested changes',items.filter(x=>x.suggestedPrice!==null).length,'Requires your approval')}${metric('Price history',intel.priceHistory?.length||0,'Approved changes recorded')}</div><section class="card"><h2 class="ctitle">Price recommendations</h2><p class="sub">No price changes are automatic. Only dated competitor entries from the last 30 days inform comparisons.</p><div class="pricingGrid">${items.map(p=>`<article class="card priceCard"><div class="metricLabel"><b>${esc(p.name)}</b><span class="status ${p.action==='INCREASE PRICE'?'warn':p.action==='INSUFFICIENT DATA'?'':' '} ">${esc(p.action)}</span></div><div class="priceMetrics"><span>My price <b>${money(p.price)}</b></span><span>Cost <b>${money(p.cost)}</b></span><span>Local median <b>${p.competitorMedian===null?'—':money(p.competitorMedian)}</b></span></div><div class="sub">${esc(p.reason)} ${p.lastChecked?'Checked '+esc(p.lastChecked):'Add verified local prices to compare.'}</div>${p.suggestedPrice!==null?`<div class="priceApply"><b>Suggested ${money(p.suggestedPrice)}</b><button class="btn secondary" data-apply-price="${esc(p.productId)}" data-price="${p.suggestedPrice}">Approve price</button></div>`:''}<details><summary>Why this price?</summary><p class="sub">Cost ${money(p.cost)} · gross margin ${p.marginPercent}% · demand ${esc(p.demand)} · stock ${p.stock} ${esc(p.unit)} · MRP ${p.mrp?money(p.mrp):'not recorded'} · competitor range ${p.competitorLow===null?'not available':money(p.competitorLow)+'–'+money(p.competitorHigh)}.</p></details></article>`).join('')}</div><h2 class="ctitle" style="margin-top:20px">Approved price changes</h2><div class="tablewrap"><table class="table"><thead><tr><th>PRODUCT</th><th>PREVIOUS</th><th>NEW PRICE</th><th>APPROVED BY</th><th>DATE</th></tr></thead><tbody>${(intel.priceHistory||[]).map(h=>`<tr><td>${esc(items.find(p=>p.productId===h.product_id)?.name||'Product')}</td><td>${money(h.old_price)}</td><td>${money(h.new_price)}</td><td>${esc(h.approved_by)}</td><td>${esc(h.approved_at)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Approved price changes will appear here.</td></tr>'}</tbody></table></div></section>`}
function competitorView(){const intel=intelligenceData(),items=intel.products||[],records=intel.competitorPrices||[];return `${head('Neighbourhood prices','Record competitor prices you have checked in person.')} ${intelligenceTabs()}<section class="card"><h2 class="ctitle">Add verified competitor price</h2><div class="formgrid competitorForm"><label>Product<select id="competitorProduct">${items.map(p=>`<option value="${esc(p.productId)}">${esc(p.name)} · ${esc(p.sku)}</option>`).join('')}</select></label><label>Competitor shop<input id="competitorName" placeholder="Shop name"></label><label>Locality<input id="competitorLocality" placeholder="Neighbourhood"></label><label>Price (₹)<input id="competitorPrice" type="number" min="0.01" step="0.01"></label><label>Date checked<input id="competitorDate" type="date" value="${today()}"></label><label>Verification note<input id="competitorNote" placeholder="Observed in store, receipt, etc."></label></div><button class="btn" id="saveCompetitor" style="margin-top:12px">Save checked price</button><p class="footnote">ShelfWise does not collect prices automatically. Older than 30 days are omitted from current suggestions.</p></section><section class="card" style="margin-top:14px"><h2 class="ctitle">Price comparison</h2><div class="tablewrap"><table class="table"><thead><tr><th>PRODUCT</th><th>MY PRICE</th><th>LOCAL MEDIAN</th><th>LOW–HIGH</th><th>DIFFERENCE</th><th>LAST CHECKED</th></tr></thead><tbody>${items.map(p=>{const diff=p.competitorMedian===null?null:(p.price-p.competitorMedian)/p.competitorMedian*100;return `<tr><td>${esc(p.name)}</td><td>${money(p.price)}</td><td>${p.competitorMedian===null?'—':money(p.competitorMedian)}</td><td>${p.competitorLow===null?'—':money(p.competitorLow)+' – '+money(p.competitorHigh)}</td><td>${diff===null?'No recent data':`${diff>0?'+':''}${diff.toFixed(1)}%`}</td><td>${p.lastChecked||'—'}</td></tr>`}).join('')}</tbody></table></div></section><section class="card" style="margin-top:14px"><h2 class="ctitle">Recent recorded checks</h2><div class="tablewrap"><table class="table"><thead><tr><th>PRODUCT</th><th>SHOP</th><th>LOCALITY</th><th>PRICE</th><th>CHECKED</th><th>NOTE</th></tr></thead><tbody>${records.map(r=>`<tr><td>${esc(items.find(p=>p.productId===r.product_id)?.name||'Product')}</td><td>${esc(r.competitor)}</td><td>${esc(r.locality||'—')}</td><td>${money(r.price)}</td><td>${esc(r.checked_on)}</td><td>${esc(r.source_note||'—')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No competitor prices recorded.</td></tr>'}</tbody></table></div></section>`}
function wireIntelligence(){const post=async(path,body)=>{const url=path+(isDemo?'?demo=1':'');const r=await fetch(url,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const x=await r.json();if(!r.ok)throw Error(x.error||'Request failed');data=(await ShelfWiseStore.load()).workspace;render();toast('Saved successfully')};document.getElementById('saveCompetitor')?.addEventListener('click',()=>post('/api/competitor-prices',{productId:document.getElementById('competitorProduct').value,competitor:document.getElementById('competitorName').value,locality:document.getElementById('competitorLocality').value,price:+document.getElementById('competitorPrice').value,checkedOn:document.getElementById('competitorDate').value,sourceNote:document.getElementById('competitorNote').value}).catch(e=>toast(e.message)));document.getElementById('saveEvent')?.addEventListener('click',()=>post('/api/seasonal-events',{name:document.getElementById('eventName').value,startDate:document.getElementById('eventStart').value,endDate:document.getElementById('eventEnd').value,note:document.getElementById('eventNote').value}).catch(e=>toast(e.message)));document.querySelectorAll('[data-apply-price]').forEach(b=>b.onclick=()=>{if(confirm(`Apply ${money(+b.dataset.price)} for this product?`))post('/api/pricing/apply',{productId:b.dataset.applyPrice,price:+b.dataset.price}).catch(e=>toast(e.message))})}

function profileView(){const demo=ShelfWiseStore.isDemo;setTimeout(loadProfile,0);return `${head('My Profile','Your account and shop details.')}<div class="row equal"><section class="card"><h2 class="ctitle">Personal information</h2><div id="profileState" class="sub">Loading profile…</div><div class="profileForm hidden" id="profileForm"><div class="profileIdentity"><img id="profilePreview" class="profile-avatar" alt="Profile picture"><label class="btn secondary">Choose photo<input id="profileFile" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><button id="removePhoto" class="outline" type="button">Remove</button></div><label>Full name<input id="profileName" maxlength="80"></label><label>Login identifier<input id="profileIdentifier" readonly></label><div class="profileActions"><button class="btn" id="saveProfile">Save changes</button><button class="outline" id="cancelProfile">Cancel</button></div></div></section><section class="card"><h2 class="ctitle">Shop information</h2><div id="profileShop" class="empty">Loading…</div><h2 class="ctitle" style="margin-top:24px">Account information</h2><div id="profileAccount" class="sub">Loading…</div></section></div>`}async function loadProfile(){const state=document.getElementById('profileState');if(!state)return;try{let profile;if(isDemo){profile={name:data.shop.owner,identifier:'Demo workspace',shop:data.shop,createdAt:null,photo:''}}else{const r=await fetch('/api/profile',{credentials:'same-origin'});if(!r.ok)throw Error('Could not load profile');profile=(await r.json()).profile}window._profile=profile;state.textContent='';const form=document.getElementById('profileForm');form.classList.remove('hidden');document.getElementById('profileName').value=profile.name;document.getElementById('profileIdentifier').value=profile.identifier;document.getElementById('profilePreview').src=profile.photo||avatarData(profile.name);document.getElementById('profileShop').innerHTML=`<p><b>${esc(profile.shop.name)}</b><br>${esc(profile.shop.category)}<br>${esc(profile.shop.address||'No address added')}</p>`;document.getElementById('profileAccount').textContent=profile.createdAt?'Created '+new Date(profile.createdAt*1000).toLocaleDateString()+' · Active':'Demo workspace · Read only';const file=document.getElementById('profileFile');file.disabled=isDemo;document.getElementById('saveProfile').disabled=isDemo;file.onchange=()=>{const f=file.files[0];if(!f)return;if(f.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)){toast('Choose a JPG, PNG or WEBP under 2 MB');file.value='';return}document.getElementById('profilePreview').src=URL.createObjectURL(f)};document.getElementById('removePhoto').onclick=()=>{window._profile.removePhoto=true;window._profile.photo='';document.getElementById('profilePreview').src=avatarData(profile.name)};document.getElementById('cancelProfile').onclick=()=>renderPage();document.getElementById('saveProfile').onclick=saveProfile}catch(e){state.textContent=e.message}}function avatarData(name){const initials=String(name||'S').split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();return 'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80"><rect width="100%" height="100%" rx="40" fill="#eaf3ec"/><text x="50%" y="55%" text-anchor="middle" font-family="sans-serif" font-size="27" fill="#28744d">${initials}</text></svg>`)}async function saveProfile(){const f=document.getElementById('profileFile').files[0],payload={name:document.getElementById('profileName').value.trim(),removePhoto:!!window._profile?.removePhoto};if(f){payload.mime=f.type;payload.image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(f)})}try{const res=await fetch('/api/profile',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await res.json();if(!res.ok)throw Error(body.error||'Could not save profile');data=(await ShelfWiseStore.load()).workspace;render();toast('Profile saved')}catch(e){toast(e.message)}}
function renderPage(){let pages={overview,sales:salesView,inventory:inventoryView,'stock-in':stockInView,purchases:purchasesView,customers:customersView,payments:paymentsView,expenses:expensesView,analytics:analyticsView,reports:reportsView,settings:settingsView,profile:profileView,'seasonal-demand':seasonalDemandView,'smart-pricing':smartPricingView,competitors:competitorView};document.getElementById('page').innerHTML=(pages[view]||overview)();wirePage();wireIntelligence();applyPagination()}
function applyPagination(){document.querySelectorAll('.table').forEach((table,index)=>{const body=table.tBodies[0];if(!body)return;const rows=[...body.rows];if(rows.length<=10)return;const sizes=[10,20,50],key=`${view}-${index}`,state=window._pages||(window._pages={}),page=state[key]||{n:1,size:10};page.n=Math.min(page.n,Math.max(1,Math.ceil(rows.length/page.size)));state[key]=page;const footer=document.createElement('div');footer.className='pagination';const start=(page.n-1)*page.size,end=Math.min(start+page.size,rows.length);rows.forEach((r,i)=>r.hidden=i<start||i>=end);footer.innerHTML=`<span>Showing ${start+1}–${end} of ${rows.length}</span><label>Rows <select aria-label="Rows per page">${sizes.map(n=>`<option ${page.size===n?'selected':''}>${n}</option>`).join('')}</select></label><button ${page.n===1?'disabled':''} data-prev>Previous</button><span>Page ${page.n} of ${Math.max(1,Math.ceil(rows.length/page.size))}</span><button ${end>=rows.length?'disabled':''} data-next>Next</button>`;table.closest('.tablewrap').after(footer);footer.querySelector('select').onchange=e=>{page.size=+e.target.value;page.n=1;renderPage()};footer.querySelector('[data-prev]').onclick=()=>{page.n--;renderPage()};footer.querySelector('[data-next]').onclick=()=>{page.n++;renderPage()}})}
function render(){shell()}function openModal(title,desc,body,submit,label='Save'){modalRoot.innerHTML=`<div class="modal"><div class="modalhead"><div><h2>${title}</h2><p>${desc}</p></div><button class="icon" id="closemodal">×</button></div><div id="modalbody">${body}</div><div class="modalfoot"><button class="btn ghost" id="cancelmodal">Cancel</button><button class="btn" id="submitmodal">${label}</button></div></div>`;modalRoot.classList.add('open');document.getElementById('closemodal').onclick=closeModal;document.getElementById('cancelmodal').onclick=closeModal;document.getElementById('submitmodal').onclick=submit}function closeModal(){modalRoot.classList.remove('open');if(window._scannerControl){window._scannerControl.stop();window._scannerControl=null}if(window._scanner){window._scanner.getTracks().forEach(t=>t.stop());window._scanner=null}const v=document.getElementById('video');if(v)v.srcObject=null}
function productForm(p={}){return `<div class="scanner"><div><b>Scan or look up an item</b><small>Scan a barcode, search a SKU, or enter identifiers manually.</small></div><button type="button" class="btn secondary" id="scanProduct">Scan barcode</button></div><label class="full">Search existing SKU / barcode<input id="productLookup" placeholder="Enter SKU or barcode to find a saved product"></label><button type="button" class="btn secondary" id="lookupExisting">Find existing product</button><label class="full">Camera<select id="cameraChoice"><option value="">Rear camera · automatic</option></select></label><div class="cameraFrame hidden" id="cameraFrame"><video id="video" playsinline muted></video><span></span></div><div class="formgrid"><label>Product name<input id="f-name" required value="${esc(p.name||'')}" placeholder="e.g. Basmati rice 1kg"></label><label>SKU<input id="f-sku" value="${esc(p.sku||'')}" placeholder="Unique shop code"></label><label>Barcode (optional)<input id="f-barcode" value="${esc(p.barcode||'')}" placeholder="EAN / UPC digits"></label><label>Category<select id="f-category">${['Produce','Dairy','Pantry','Snacks','Beverages','Other'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Unit<input id="f-unit" value="${esc(p.unit||'unit')}" placeholder="kg, pack, bottle"></label><label>Purchase price (₹)<input id="f-cost" type="number" min="0" value="${p.cost||''}"></label><label>Selling price (₹)<input id="f-price" type="number" min="0" value="${p.price||''}"></label><label>MRP limit (₹, optional)<input id="f-mrp" type="number" min="0" value="${p.mrp||''}"></label><label>Initial / current stock<input id="f-stock" type="number" min="0" value="${p.stock??0}"></label><label>Reorder threshold<input id="f-threshold" type="number" min="0" value="${p.threshold??5}"></label><label>Supplier lead time (days)<input id="f-lead" type="number" min="1" value="${p.leadTimeDays??7}"></label><label class="full">Expiry date (optional)<input id="f-expiry" type="date" value="${p.expiry||''}"></label></div>`}
function openProduct(p,scannedCode=''){openModal(p?'Review product':'Add product','A barcode is an identifier; enter product details after scanning.',productForm(p||{barcode:scannedCode}),async()=>{const name=document.getElementById('f-name').value.trim(),sku=document.getElementById('f-sku').value.trim()||'SW-'+Date.now().toString(36).toUpperCase();if(!name)return toast('Product name is required');if(data.products.some(x=>x.sku.toLowerCase()===sku.toLowerCase()&&x.id!==p?.id))return toast('That SKU is already in use');const barcode=document.getElementById('f-barcode').value.trim();if(barcode&&data.products.some(x=>String(x.barcode||'').toLowerCase()===barcode.toLowerCase()&&x.id!==p?.id))return toast('That barcode is already assigned to another product');const obj={...(p||{}),id:p?.id||'p'+Date.now(),name,sku,barcode,category:document.getElementById('f-category').value,unit:document.getElementById('f-unit').value||'unit',cost:+document.getElementById('f-cost').value||0,price:+document.getElementById('f-price').value||0,mrp:+document.getElementById('f-mrp')?.value||0,stock:+document.getElementById('f-stock').value||0,threshold:+document.getElementById('f-threshold').value||0,leadTimeDays:Math.max(1,+document.getElementById('f-lead').value||7),expiry:document.getElementById('f-expiry').value,sold:p?.sold||0,archived:false};if(p)data.products[data.products.findIndex(x=>x.id===p.id)]=obj;else data.products.push(obj);const ok=await save();if(ok){closeModal();render();toast(p?'Product updated':'Product added to inventory')}},p?'Save product':'Add product');if(scannedCode){document.getElementById('f-barcode').value=scannedCode;document.getElementById('f-sku').value='SW-'+Date.now().toString(36).toUpperCase()}document.getElementById('lookupExisting').onclick=()=>{const code=document.getElementById('productLookup').value.trim(),found=productForCode(code);if(found){closeModal();openProduct(found);toast(found.name+' already exists · review product details')}else if(code){document.getElementById('f-barcode').value=code;toast('No match found · complete the new product details')}};document.getElementById('productLookup').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();document.getElementById('lookupExisting').click()}};document.getElementById('scanProduct').onclick=()=>startScan((code,found)=>{closeModal();openProduct(found);toast(found.name+' found · review product details')},code=>{const field=document.getElementById('f-barcode');if(field)field.value=code;const skuField=document.getElementById('f-sku');if(skuField&&!skuField.value)skuField.value='SW-'+Date.now().toString(36).toUpperCase();toast('Barcode captured · enter product details')})}
function productForCode(v){v=String(v||'').trim().toLowerCase();return data.products.find(p=>!p.archived&&(String(p.sku||'').toLowerCase()===v||String(p.barcode||'').toLowerCase()===v))||null}
function stopScan(){clearInterval(window._scanTimer);window._scanTimer=null;if(window._scannerControl){try{window._scannerControl.stop()}catch{}window._scannerControl=null}if(window._scanner){window._scanner.getTracks().forEach(t=>t.stop());window._scanner=null}let v=document.getElementById('video');if(v)v.srcObject=null}
function loadZXing(){if(window.ZXingBrowser)return Promise.resolve();if(window._zxingPromise)return window._zxingPromise;window._zxingPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://unpkg.com/@zxing/browser@0.2.1';script.onload=()=>window.ZXingBrowser?resolve():reject(new Error('Barcode scanner unavailable'));script.onerror=()=>reject(new Error('Barcode scanner library could not be loaded · enter the SKU manually'));document.head.append(script)});return window._zxingPromise}
function startScan(ok,unknown){let v=document.getElementById('video'),f=document.getElementById('cameraFrame'),sel=document.getElementById('cameraChoice'),locked=false;if(!v||!f)return;if(!navigator.mediaDevices?.getUserMedia){toast('Camera needs HTTPS or localhost · enter code manually');return}f.classList.remove('hidden');let fail=e=>{stopScan();f.classList.add('hidden');toast(e?.name==='NotAllowedError'?'Camera permission denied · enter code manually':'Camera unavailable · use manual entry')};let found=raw=>{if(!raw||locked)return;locked=true;let p=productForCode(raw);stopScan();p?ok(raw,p):unknown(raw,null)};let open=async id=>{stopScan();try{let stream=await navigator.mediaDevices.getUserMedia({video:id?{deviceId:{exact:id}}:{facingMode:{ideal:'environment'}},audio:false});window._scanner=stream;v.srcObject=stream;await v.play();await devices();decode()}catch(e){fail(e)}};async function devices(){if(!sel)return;let cams=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='videoinput'),active=window._scanner?.getVideoTracks()[0]?.getSettings().deviceId;sel.innerHTML='<option value="">Automatic · '+esc(window._scanner?.getVideoTracks()[0]?.label||'camera')+'</option>'+cams.map((c,i)=>'<option value="'+esc(c.deviceId)+'" '+(c.deviceId===active?'selected':'')+'>'+esc(c.label||('Camera '+(i+1)))+'</option>').join('');sel.onchange=()=>open(sel.value)}function decode(){if('BarcodeDetector'in window){try{let formats=['ean_13','ean_8','upc_a','upc_e','code_128','qr_code'];if(BarcodeDetector.getSupportedFormats)BarcodeDetector.getSupportedFormats().then(a=>{let d=new BarcodeDetector({formats:formats.filter(x=>a.includes(x))});window._scanTimer=setInterval(async()=>{try{if(v.readyState>=2){let r=await d.detect(v);if(r.length)found(r[0].rawValue)}}catch{}},160)}).catch(fail);else{let d=new BarcodeDetector({formats});window._scanTimer=setInterval(async()=>{try{let r=await d.detect(v);if(r.length)found(r[0].rawValue)}catch{}},160)}return}catch{}}if(window.ZXingBrowser?.BrowserMultiFormatReader){new ZXingBrowser.BrowserMultiFormatReader().decodeFromVideoElement(v,r=>{if(r)found(r.getText())}).then(c=>window._scannerControl=c).catch(fail)}else{loadZXing().then(()=>{if(window.ZXingBrowser?.BrowserMultiFormatReader)new ZXingBrowser.BrowserMultiFormatReader().decodeFromVideoElement(v,r=>{if(r)found(r.getText())}).then(c=>window._scannerControl=c).catch(fail);else fail(new Error('Barcode scanner unavailable'))}).catch(fail)}}open('')}
function openSale(){let cart=[],rid='S-'+crypto.randomUUID();openModal('New sale','Scan or enter a product SKU/barcode. Inventory changes only after confirmation.','<button id="saleScan" class="btn secondary">Scan barcode</button><label>Camera<select id="cameraChoice"><option value="">Rear camera · automatic</option></select></label><div class="cameraFrame hidden" id="cameraFrame"><video id="video" playsinline muted></video></div><div class="filters"><input id="saleCode" placeholder="SKU or barcode"><button id="saleAdd" class="btn secondary">Add</button></div><div id="saleLines"></div><select id="saleMethod"><option>Cash</option><option>UPI</option><option>Card</option><option>Credit</option></select><label id="saleCustomerWrap" class="hidden">Customer<select id="saleCustomer">'+data.customers.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+' · '+money(c.balance)+' due</option>').join('')+'</select></label>',async()=>{if(!cart.length)return toast('Add an item');const method=document.getElementById('saleMethod').value;if(method==='Credit'&&!data.customers.length)return toast('Add a customer before using credit');try{await protectedRequest(()=>ShelfWiseStore.recordSale({requestId:rid,sale:{id:rid,date:today(),method,customerId:method==='Credit'?document.getElementById('saleCustomer').value:'',items:cart.map(x=>({productId:x.id,qty:x.qty}))}}));closeModal();render();toast('Sale confirmed')}catch{}},'Confirm sale');function draw(){const el=document.getElementById('saleLines');el.innerHTML=cart.map((x,i)=>'<div class="cartline"><span>'+esc(x.name)+' · '+money(x.price)+'</span><input type="number" min="1" max="'+x.stock+'" value="'+x.qty+'" data-saleqty="'+i+'"><b>'+money(x.price*x.qty)+'</b><button class="outline" data-saleremove="'+i+'">×</button></div>').join('')||'<div class="empty">Bill is empty</div>';el.querySelectorAll('[data-saleqty]').forEach(e=>e.onchange=()=>{const x=cart[+e.dataset.saleqty];x.qty=Math.max(1,Math.min(x.stock,+e.value||1));draw()});el.querySelectorAll('[data-saleremove]').forEach(e=>e.onclick=()=>{cart.splice(+e.dataset.saleremove,1);draw()})}function add(code){let p=productForCode(code);if(!p)return toast('Product not found');let x=cart.find(a=>a.id===p.id);if(x)x.qty++;else cart.push({...p,qty:1});draw()}document.getElementById('saleScan').onclick=()=>startScan(c=>add(c),()=>toast('Unknown barcode · add product in Inventory'));document.getElementById('saleAdd').onclick=()=>add(document.getElementById('saleCode').value);document.getElementById('saleMethod').onchange=e=>document.getElementById('saleCustomerWrap').classList.toggle('hidden',e.target.value!=='Credit');draw()}
function openStockIn(){let lines=[];openModal('Stock In','Scan product barcodes or select an existing product, then confirm.','<button id="stockScan" class="btn secondary">Scan barcode</button><label>Camera<select id="cameraChoice"><option value="">Rear camera · automatic</option></select></label><div class="cameraFrame hidden" id="cameraFrame"><video id="video" playsinline muted></video></div><select id="stockProduct"><option value="">Select product</option>'+data.products.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · '+esc(p.sku)+'</option>').join('')+'</select><button id="stockAdd" class="btn secondary">Add</button><input id="stockCode" placeholder="SKU/barcode"><button id="stockFind" class="btn secondary">Find</button><div id="stockLines"></div><input id="stockSupplier" placeholder="Supplier"><input id="stockInvoice" placeholder="Invoice"><input id="stockBatch" placeholder="Batch"><input id="stockExpiry" type="date">',async()=>{if(!lines.length)return toast('Add product');let rid='GR-'+crypto.randomUUID();try{await protectedRequest(()=>ShelfWiseStore.receiveStock({requestId:rid,purchase:{supplier:document.getElementById('stockSupplier').value||'Supplier',invoice:document.getElementById('stockInvoice').value,date:today()},items:lines.map((x,i)=>({id:rid+i,productId:x.id,qty:Math.max(1,+document.querySelector('[data-stockqty="'+i+'"]')?.value||x.qty),cost:Math.max(0,+document.querySelector('[data-stockcost="'+i+'"]')?.value||x.cost),supplier:document.getElementById('stockSupplier').value||'Supplier',invoice:document.getElementById('stockInvoice').value,batch:document.getElementById('stockBatch').value,expiry:document.getElementById('stockExpiry').value}))}));closeModal();render();toast('Stock received')}catch{}},'Confirm receipt');function draw(){document.getElementById('stockLines').innerHTML=lines.map((x,i)=>'<div class="cartline">'+esc(x.name)+'<input type="number" min="1" value="'+x.qty+'" data-stockqty="'+i+'"><input type="number" min="0" aria-label="Unit cost" value="'+x.cost+'" data-stockcost="'+i+'"><span>'+money(x.cost*x.qty)+'</span><button class="outline" data-stockremove="'+i+'">×</button></div>').join('');document.querySelectorAll('[data-stockqty]').forEach(e=>e.onchange=()=>{lines[+e.dataset.stockqty].qty=Math.max(1,+e.value||1);draw()});document.querySelectorAll('[data-stockcost]').forEach(e=>e.onchange=()=>{lines[+e.dataset.stockcost].cost=Math.max(0,+e.value||0);draw()});document.querySelectorAll('[data-stockremove]').forEach(e=>e.onclick=()=>{lines.splice(+e.dataset.stockremove,1);draw()})}function add(p){if(!p)return toast('Product not found');let x=lines.find(a=>a.id===p.id);if(x)x.qty++;else lines.push({...p,qty:1});draw()}document.getElementById('stockScan').onclick=()=>startScan((c,p)=>add(p),()=>toast('Unknown barcode · register it first'));document.getElementById('stockAdd').onclick=()=>add(data.products.find(p=>p.id===document.getElementById('stockProduct').value));document.getElementById('stockFind').onclick=()=>add(productForCode(document.getElementById('stockCode').value))}
function openPurchase(){openStockIn()}
function openStock(){let requestId=null;openModal('Receive stock','Record an inventory adjustment. For supplier purchases use Purchases.',`<div class="formgrid"><label class="full">Product<select id="adj-product">${data.products.filter(p=>!p.archived).map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.stock} ${esc(p.unit)} now</option>`).join('')}</select></label><label>Quantity to add<input id="adj-qty" type="number" min="1" value="1"></label><label>Reason<input id="adj-reason" placeholder="Opening count / correction"></label></div>`,async()=>{let id=document.getElementById('adj-product').value,p=data.products.find(p=>p.id===id),q=+document.getElementById('adj-qty').value;if(!p||q<1)return toast('Enter a valid quantity');if(!requestId)requestId='ADJ-'+crypto.randomUUID();const submit=document.getElementById('submitmodal');submit.disabled=true;try{await protectedRequest(()=>ShelfWiseStore.receiveStock({requestId,purchase:{id:requestId,productId:id,qty:q,cost:p.cost,supplier:document.getElementById('adj-reason').value||'Stock adjustment',date:today(),invoice:'Adjustment'}}));requestId=null;closeModal();render();toast('Stock updated')}catch{}finally{if(submit.isConnected)submit.disabled=false}},'Add stock')}
function openExpense(){openModal('Record an expense','Keep operating costs separate from revenue and stock purchases.',`<div class="formgrid"><label>Category<select id="ex-category"><option>Rent</option><option>Electricity</option><option>Salaries</option><option>Transportation</option><option>Packaging</option><option>Miscellaneous</option></select></label><label>Amount (₹)<input id="ex-amount" type="number" min="1" required></label><label>Date<input id="ex-date" type="date" value="${today()}"></label><label>Note<input id="ex-note" placeholder="Optional details"></label></div>`,()=>{let amount=+document.getElementById('ex-amount').value;if(amount<=0)return toast('Enter a valid amount');data.expenses.push({id:'e'+Date.now(),category:document.getElementById('ex-category').value,amount,date:document.getElementById('ex-date').value,note:document.getElementById('ex-note').value});save();closeModal();render();toast('Expense recorded')},'Record expense')}
function openCustomer(){openModal('Add customer','Set up a customer credit account.',`<div class="formgrid"><label>Customer name<input id="c-name" required></label><label>Phone number<input id="c-phone" type="tel"></label><label>Opening balance (₹)<input id="c-balance" type="number" min="0" value="0"></label><label>Due date<input id="c-due" type="date"></label></div>`,()=>{let name=document.getElementById('c-name').value.trim();if(!name)return toast('Customer name is required');data.customers.push({id:'c'+Date.now(),name,phone:document.getElementById('c-phone').value,balance:+document.getElementById('c-balance').value||0,due:document.getElementById('c-due').value,history:[]});save();closeModal();render();toast('Customer account added')},'Add customer')}
function repay(id){let c=data.customers.find(c=>c.id===id);openModal('Record repayment',`${esc(c.name)} · Balance ${money(c.balance)}`,`<div class="formgrid"><label>Amount received (₹)<input id="repay-amount" type="number" min="1" max="${c.balance}" value="${c.balance}"></label><label>Payment method<select id="repay-method"><option>Cash</option><option>UPI</option><option>Card</option></select></label></div>`,()=>{let a=+document.getElementById('repay-amount').value;if(a<=0||a>c.balance)return toast('Enter an amount within the outstanding balance');c.balance-=a;c.history.push({date:today(),amount:a,method:document.getElementById('repay-method').value});save();closeModal();render();toast(`Repayment of ${money(a)} recorded`)},'Record payment')}
function openReturn(saleId){const sale=data.sales.find(x=>x.id===saleId);if(!sale)return;const available=(sale.details||[]).filter(x=>x.qty>(x.returned||0));if(!available.length)return toast('All items from this sale have already been returned');openModal('Record a returned item','Returned units go back into stock and are excluded from sales demand predictions.',`<div class="formgrid"><label class="full">Product<select id="return-product">${available.map(x=>`<option value="${x.productId}" data-remaining="${x.qty-(x.returned||0)}">${esc(x.product)} · ${x.qty-(x.returned||0)} unreturned</option>`).join('')}</select></label><label>Quantity returned<input id="return-qty" type="number" min="1" value="1"></label><label class="full">Reason<input id="return-reason" placeholder="Optional reason"></label></div>`,async()=>{const productId=document.getElementById('return-product').value,qty=+document.getElementById('return-qty').value,option=document.querySelector('#return-product option:checked'),max=+(option?.dataset.remaining||0);if(qty<1||qty>max)return toast(`Enter a quantity from 1 to ${max}`);const btn=document.getElementById('submitmodal');btn.disabled=true;try{const requestId='R-'+crypto.randomUUID();await protectedRequest(()=>ShelfWiseStore.recordReturn({requestId,saleId,items:[{productId,qty}],reason:document.getElementById('return-reason').value}));closeModal();render();toast('Return recorded · stock restored')}catch{}finally{if(btn.isConnected)btn.disabled=false}},'Confirm return')}
function openDraftPurchase(productId,qty){const p=data.products.find(x=>x.id===productId),ins=(data.insights||[]).find(x=>x.productId===productId);if(!p)return;openModal('Create purchase draft',`This saves a suggested order for review. Inventory will not change until goods are received.`, `<div class="formgrid"><label class="full">Product<input value="${esc(p.name)} · ${esc(p.sku)}" disabled></label><label>Suggested quantity<input id="draft-qty" type="number" min="1" value="${Math.max(1,qty||1)}"></label><label>Unit cost (₹)<input id="draft-cost" type="number" min="0" value="${p.cost}"></label><label>Supplier<input id="draft-supplier" placeholder="Supplier to confirm"></label><label>Lead time<input value="${ins?.leadTimeDays||p.leadTimeDays||7} days" disabled></label><label class="full">Note<input id="draft-note" placeholder="Optional note for the shop owner"></label></div>`,async()=>{const quantity=+document.getElementById('draft-qty').value;if(quantity<1)return toast('Enter a valid order quantity');const btn=document.getElementById('submitmodal');btn.disabled=true;try{const requestId='D-'+crypto.randomUUID();await protectedRequest(()=>ShelfWiseStore.createPurchaseDraft({requestId,purchase:{id:requestId,productId:p.id,qty:quantity,cost:+document.getElementById('draft-cost').value||p.cost,supplier:document.getElementById('draft-supplier').value||'Supplier to confirm',date:today(),invoice:document.getElementById('draft-note').value}}));closeModal();navigate('purchases');toast('Draft saved · inventory unchanged')}catch{}finally{if(btn.isConnected)btn.disabled=false}},'Save draft')}
function csv(type){let rows=[],filename=type.toLowerCase().replaceAll(' ','-')+'-report.csv';if(type==='Sales')rows=[['Invoice','Date','Items','Method','Customer','Revenue','Cost'],...data.sales.map(s=>[s.id,s.date,s.items,s.method,s.customer,s.total,s.cost])];if(type==='Inventory')rows=[['Name','SKU','Category','Purchase price','Selling price','Stock','Unit','Stock value','Units sold','Expiry'],...data.products.map(p=>[p.name,p.sku,p.category,p.cost,p.price,p.stock,p.unit,p.cost*p.stock,p.sold,p.expiry])];if(type==='Purchases')rows=[['Invoice','Date','Supplier','Product','Quantity','Unit cost','Total'],...data.purchases.map(p=>[p.invoice,p.date,p.supplier,p.product,p.qty,p.cost,p.qty*p.cost])];if(type==='Profit & loss')rows=[['Metric','Amount'],['Revenue',data.sales.reduce((a,s)=>a+s.total,0)],['Cost of goods sold',data.sales.reduce((a,s)=>a+s.cost,0)],['Gross profit',data.sales.reduce((a,s)=>a+s.total-s.cost,0)],['Operating expenses',data.expenses.reduce((a,e)=>a+e.amount,0)],['Net profit estimate',data.sales.reduce((a,s)=>a+s.total-s.cost,0)-data.expenses.reduce((a,e)=>a+e.amount,0)],['Outstanding credit',pending()]];let txt=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),blob=new Blob(['\ufeff'+txt],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();URL.revokeObjectURL(a.href);toast(filename+' downloaded')}
function wirePage(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{switch(b.dataset.action){case'sale':openSale();break;case'addproduct':openProduct();break;case'scanadd':openProduct();document.getElementById('scanProduct')?.click();break;case'applyrange':customFrom=document.getElementById('customFrom')?.value||'';customTo=document.getElementById('customTo')?.value||today();period='Custom';render();break;case'stock':openStock();break;case'stockin':openStockIn();break;case'purchase':openPurchase();break;case'customer':openCustomer();break;case'expense':openExpense();break;case'savesettings':data.shop.name=document.getElementById('sname').value.trim()||data.shop.name;data.shop.owner=document.getElementById('ownername').value.trim()||data.shop.owner;data.shop.category=document.getElementById('scat').value;data.shop.address=document.getElementById('saddress').value;save().then(()=>render());toast('Shop profile saved');break}});document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>openProduct(data.products.find(p=>p.id===b.dataset.product)));document.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>openDraftPurchase(b.dataset.draft,+b.dataset.qty));document.querySelectorAll('[data-dismiss-insight]').forEach(b=>b.onclick=()=>{dismissedInsights.add(b.dataset.dismissInsight);renderPage()});document.querySelectorAll('[data-return]').forEach(b=>b.onclick=()=>openReturn(b.dataset.return));document.querySelectorAll('[data-qr]').forEach(b=>b.onclick=()=>qrModal(data.products.find(p=>p.id===b.dataset.qr))); document.querySelectorAll('[data-repay]').forEach(b=>b.onclick=()=>repay(b.dataset.repay));document.querySelectorAll('[data-csv]').forEach(b=>b.onclick=()=>csv(b.dataset.csv));document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;if(period!=='Custom'){customFrom='';customTo=''}render()});document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{let t=data.tasks[+b.dataset.task];t.done=!t.done;save();render()});document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>navigate(b.dataset.goto));document.querySelectorAll('[data-invoice]').forEach(b=>b.onclick=()=>{let s=data.sales.find(x=>x.id===b.dataset.invoice);printInvoice(s)});let si=document.getElementById('search');if(si)si.oninput=()=>{search=si.value;if(window._pages)delete window._pages[view+'-0'];let pos=si.selectionStart;renderPage();let el=document.getElementById('search');el.focus();el.setSelectionRange(pos,pos)};let fi=document.getElementById('invfilter');if(fi)fi.onchange=()=>{filter=fi.value;if(window._pages)window._pages={};renderPage()};let th=document.getElementById('themeSelect');if(th)th.onchange=()=>{document.body.classList.toggle('dark',th.value==='Dark');localStorage.setItem('shelfwise-theme',th.value.toLowerCase());render()};let reset=document.getElementById('resetsettings');if(reset&&isDemo)reset.onclick=()=>{if(confirm('Reset demo data?'))ShelfWiseStore.resetDemo().then(r=>{data=r.workspace;render();toast('Demo data reset')}).catch(e=>toast(e.message))};document.querySelectorAll('[data-action="savesettings"]').forEach(()=>{});}
function loadQRCode(){if(window.QRCode)return Promise.resolve();if(window._qrPromise)return window._qrPromise;window._qrPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js';script.onload=()=>window.QRCode?resolve():reject(new Error('QR generator unavailable'));script.onerror=()=>reject(new Error('QR generator unavailable'));document.head.append(script)});return window._qrPromise}function qrModal(p){openModal('Product QR code',`${esc(p.name)} · ${esc(p.sku)}`,`<div id="qrcode"></div><p style="text-align:center;font-size:11px">Scan this code to identify the product during billing.</p><div class="footnote" style="text-align:center">QR value: ${esc(p.sku)}</div>`,()=>{let canvas=document.querySelector('#qrcode canvas'),img=document.querySelector('#qrcode img');let url=canvas?.toDataURL('image/png')||img?.src;if(url){let a=document.createElement('a');a.href=url;a.download=`${p.sku}-qr.png`;a.click();toast('QR downloaded')}closeModal()},'Download QR');loadQRCode().then(()=>new QRCode(document.getElementById('qrcode'),{text:p.sku,width:180,height:180})).catch(()=>{const el=document.getElementById('qrcode');if(el)el.textContent='QR generator unavailable · SKU: '+p.sku})}
function printInvoice(s){let w=window.open('','_blank','width=420,height=600');if(!w)return toast('Allow pop-ups to print invoice');w.document.write(`<title>Invoice ${esc(s.id)}</title><body style="font:14px Arial;padding:30px"><h2>${esc(data.shop.name)}</h2><p>${esc(data.shop.address)}</p><hr><p>Invoice: ${esc(s.id)}<br>Date: ${s.date}<br>Customer: ${esc(s.customer||'Walk-in')}<br>Payment: ${esc(s.method)}</p><hr><h3>Total: ${money(s.total)}</h3><p>Thank you for shopping with us.</p><script>window.print()<\/script></body>`);w.document.close()}
// restore appearance preference
const savedTheme=localStorage.getItem('shelfwise-theme');if(savedTheme==='dark')document.body.classList.add('dark');async function boot(){try{const result=await ShelfWiseStore.load();data=result.workspace;render()}catch(err){document.getElementById('root').innerHTML=`<main class="card" style="margin:40px;padding:24px"><h1>Workspace unavailable</h1><p>${esc(err.message)}</p><a class="btn" href="/login">Sign in</a><a class="outline" href="/app?demo=1">Open demo</a></main>`}}boot();
})();
